package com.lexorion.payroll.service;import static com.lexorion.payroll.api.PayrollDtos.*;import com.lexorion.payroll.api.PayrollException;import com.lexorion.payroll.domain.*;import com.lexorion.payroll.repository.*;import com.lexorion.payroll.workforce.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;@Service public class PayrollEmployeeService{private final PayrollWorkspaceScope scope;private final PayrollEmployeeRepository employees;private final WorkforceEmployeeVerifier workforce;public PayrollEmployeeService(PayrollWorkspaceScope s,PayrollEmployeeRepository e,WorkforceEmployeeVerifier w){scope=s;employees=e;workforce=w;}@Transactional(readOnly=true)public List<PayrollEmployeeResponse> list(){return employees.findByWorkspaceIdOrderByEmployeeCodeAsc(scope.context().workspaceId()).stream().map(PayrollEmployeeResponse::from).toList();}@Transactional(readOnly=true)public PayrollEmployeeResponse get(String raw){return PayrollEmployeeResponse.from(find(raw));}@Transactional(isolation=Isolation.READ_COMMITTED)public PayrollEmployeeResponse create(CreatePayrollEmployee r){PayrollWorkspace w=scope.locked();String code=code(r.employeeCode());if(!code.matches("^[A-Z0-9][A-Z0-9._-]{0,63}$"))throw new PayrollException(400,"Invalid employee code");WorkforceEmployeeVerifier.Verification verified=workforce.verify(code,scope.context());if(!verified.exists()||!code.equals(verified.employeeCode()))throw new PayrollException(502,"Workforce returned an invalid verification response");if(verified.employmentStatus()==WorkforceEmploymentStatus.RESIGNED||verified.employmentStatus()==WorkforceEmploymentStatus.TERMINATED)throw new PayrollException(409,"Workforce employment status does not allow new Payroll configuration");if(employees.existsByWorkspaceIdAndEmployeeCode(w.getId(),code))throw new PayrollException(409,"Payroll employee already exists");PayrollEmployee e=new PayrollEmployee();e.setWorkspace(w);e.setEmployeeCode(code);e.setStatus(r.status());e.setCurrency(currency(r.currency()));e.setPayFrequency(r.payFrequency());e.setEffectiveFrom(r.effectiveFrom());return PayrollEmployeeResponse.from(employees.saveAndFlush(e));}@Transactional(isolation=Isolation.READ_COMMITTED)public PayrollEmployeeResponse update(String raw,UpdatePayrollEmployee r){scope.locked();PayrollEmployee e=find(raw);if(r.status()!=null)e.setStatus(r.status());if(r.currency()!=null)e.setCurrency(currency(r.currency()));if(r.payFrequency()!=null)e.setPayFrequency(r.payFrequency());if(r.effectiveFrom()!=null)e.setEffectiveFrom(r.effectiveFrom());return PayrollEmployeeResponse.from(employees.saveAndFlush(e));}PayrollEmployee find(String raw){return employees.findByWorkspaceIdAndEmployeeCode(scope.context().workspaceId(),code(raw)).orElseThrow(()->new PayrollException(404,"Payroll employee not found"));}static String code(String value){return value==null?"":value.trim().toUpperCase(Locale.ROOT);}static String currency(String value){String v=value==null?"":value.trim().toUpperCase(Locale.ROOT);if(!v.matches("^[A-Z]{3}$"))throw new PayrollException(400,"Currency must be a three-letter ISO code");return v;}}
